@Composable private fun AuditScreen(vm:RepoAuditViewModel,onFolder:()->Unit,onBack:()->Unit){val repos by vm.repos.collectAsStateWithLifecycle();val branches by vm.branches.collectAsStateWithLifecycle();val history by vm.history.collectAsStateWithLifecycle();val loading by vm.loading.collectAsStateWithLifecycle();val msg by vm.message.collectAsStateWithLifecycle();val run by vm.run.collectAsStateWithLifecycle();val scope by vm.scopePreview.collectAsStateWithLifecycle();val preflight by vm.preflight.collectAsStateWithLifecycle();val privacy by vm.privacyConfirmed.collectAsStateWithLifecycle();val allocation by vm.auditAllocationVersion.collectAsStateWithLifecycle();val ctx=LocalContext.current;var keyPanel by rememberSaveable{mutableStateOf(!vm.githubConfigured())};var key by rememberSaveable{mutableStateOf("")};var output by rememberSaveable{mutableStateOf(false)};var search by rememberSaveable{mutableStateOf("")};var selectedName by rememberSaveable{mutableStateOf("")};var ref by rememberSaveable{mutableStateOf("")};var rules by rememberSaveable{mutableStateOf("")};var advanced by rememberSaveable{mutableStateOf(false)};var showScope by remember{mutableStateOf(false)};var mode by rememberSaveable{mutableStateOf(if(run.repoFullName.isNotBlank())"run" else "new")};var historyItem by remember{mutableStateOf<RepoAuditHistoryItem?>(null)};val owner=LocalLifecycleOwner.current;DisposableEffect(owner){val o=LifecycleEventObserver{_,e->if(e==Lifecycle.Event.ON_RESUME)vm.refreshAuditAllocation()};owner.lifecycle.addObserver(o);onDispose{owner.lifecycle.removeObserver(o)}};LaunchedEffect(Unit){if(vm.githubConfigured())vm.loadRepos();vm.loadHistory()};val selected=repos.firstOrNull{it.fullName==selectedName};if(showScope&&scope!=null)ScopeDialog(scope!!,vm){showScope=false};historyItem?.let{HistoryDialog(it,{vm.deleteHistory(it.id);historyItem=null}){historyItem=null}};val running=run.stage in listOf(RepoAuditStage.SNAPSHOT,RepoAuditStage.INDEPENDENT,RepoAuditStage.PEER_REVIEW,RepoAuditStage.VERIFY,RepoAuditStage.CHAIRMAN);val notify=rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()){};Scaffold(topBar={TopAppBar(title={Column{Text("Repository Audit",fontWeight=FontWeight.Bold);Text("OmniCouncil · v${BuildConfig.VERSION_NAME}",style=MaterialTheme.typography.labelSmall)}},navigationIcon={IconButton(onClick=onBack){Icon(Icons.Default.ArrowBack,"Back")}},actions={IconButton(onClick={keyPanel=!keyPanel}){Icon(Icons.Default.Key,"GitHub")};IconButton(onClick={output=!output}){Icon(Icons.Default.Folder,"Output")}})}){pad->LazyColumn(Modifier.fillMaxSize().padding(pad),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){if(keyPanel)item{KeyCard(vm,key,{key=it},{key="";keyPanel=false})};if(output)item{OutputCard(vm,onFolder)};msg?.let{item{Notice(it,vm::clearMessage)}};if(run.repoFullName.isNotBlank()||history.isNotEmpty())item{Row{FilterChip(mode=="new",{mode="new"},label={Text("New audit")});Spacer(Modifier.width(8.dp));FilterChip(mode=="run",{mode="run"},label={Text(if(running)"Active / history" else "Audit history")})}};if(mode=="run"){if(run.repoFullName.isNotBlank()){item{Progress(run,vm)};if(run.modelAudits.isNotEmpty())item{Evidence(run,vm)};if(run.peerReviews.isNotEmpty())item{Peer(run,vm)};if(run.verificationMemo.isNotBlank())item{LongCard("Verification",run.verificationMemo)};if(run.finalReport.isNotBlank())item{LongCard("Final report · ${vm.modelLabel(run.chairmanModel)}",run.finalReport)}};if(history.isNotEmpty()){item{Text("Previous completed audits",fontWeight=FontWeight.Bold)};items(history,key={it.id}){h->ElevatedCard(Modifier.fillMaxWidth().clickable{historyItem=h}){ListItem(headlineContent={Text(h.repoFullName)},supportingContent={Text("${h.commitSha.take(10)} · ${h.requiredFiles} files · ${DateFormat.getDateTimeInstance().format(Date(h.finishedAt))}")})}}}}else if(!running){if(!vm.githubConfigured())item{ElevatedCard{Text("Connect GitHub from the key button above.",Modifier.padding(14.dp))}}else if(selected==null){item{Text("Choose repository",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold)};item{OutlinedTextField(search,{search=it},Modifier.fillMaxWidth(),label={Text("Search repositories")},leadingIcon={Icon(Icons.Default.Search,null)},trailingIcon={IconButton(onClick=vm::loadRepos){Icon(Icons.Default.Refresh,"Reload")}})};if(loading)item{LinearProgressIndicator(Modifier.fillMaxWidth())};items(repos.filter{search.isBlank()||it.fullName.contains(search,true)},key={it.fullName}){r->ElevatedCard(Modifier.fillMaxWidth().clickable{selectedName=r.fullName;ref=r.defaultBranch;rules=vm.scopeRules(r.fullName);vm.clearScopePreview();vm.loadBranches(r.fullName)}){ListItem(headlineContent={Text(r.fullName)},supportingContent={Text("${if(r.privateRepo)"Private" else "Public"} · ${r.defaultBranch}")},trailingContent={Icon(Icons.Default.ChevronRight,null)})}}}else{val repo=selected;item{Row(verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text("New repository audit",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text(repo.fullName)};TextButton(onClick={selectedName="";vm.clearScopePreview()}){Text("Change")}}};item{Step("1","Repository & scope"){Revision(ref,branches,repo.defaultBranch,{ref=it;vm.clearScopePreview()},{advanced=!advanced});if(advanced)OutlinedTextField(ref,{ref=it;vm.clearScopePreview()},Modifier.fillMaxWidth(),label={Text("Tag / commit / revision")});OutlinedTextField(rules,{rules=it;vm.clearScopePreview()},Modifier.fillMaxWidth(),label={Text("Optional scope rules")},minLines=3)}};item{Step("2","Review team"){val rs=vm.auditReviewerModels();rs.forEachIndexed{i,id->Text("Reviewer ${i+1} · ${vm.modelLabel(id)}",style=MaterialTheme.typography.labelMedium)};Text("Final Reviewer · ${vm.modelLabel(vm.auditChairman())}",style=MaterialTheme.typography.labelMedium);OutlinedButton(onClick={ctx.startActivity(Intent(ctx,AuditModelAllocationActivity::class.java))}){Text("Configure team")}}};item{Step("3","Prepare scope"){Text("Model access and audit capability are checked before preparation.");Button(onClick={vm.prepareScope(repo,ref,rules)},enabled=!loading&&vm.auditAllocationReady(),modifier=Modifier.fillMaxWidth()){Text(if(scope==null)"Prepare audit scope" else "Rebuild audit scope")};if(loading)OutlinedButton(onClick=vm::cancelScopePreparation){Text("Cancel")}}};val p=scope?.takeIf{it.repoFullName==repo.fullName};if(p!=null)item{ScopeSummary(p){showScope=true}};if(p!=null&&p.unresolvedFiles>0)item{Button(onClick=vm::retryAutomaticScope){Text("Retry ${p.unresolvedFiles} unresolved")}};if(p!=null&&p.unresolvedFiles==0&&preflight!=null){item{Preflight(preflight!!,privacy,{vm.setPrivacyConfirmed(it)},{if(Build.VERSION.SDK_INT>=33&&ContextCompat.checkSelfPermission(ctx,Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)notify.launch(Manifest.permission.POST_NOTIFICATIONS)})};item{Button(onClick={vm.start(repo,ref);mode="run"},enabled=privacy&&!loading,modifier=Modifier.fillMaxWidth()){Text("Start validated audit")}}}}}else if(running)item{Button(onClick={mode="run"}){Text("Open active audit")}}}}}
@Composable private fun Step(n:String,t:String,c:@Composable ColumnScope.()->Unit){ElevatedCard{Column(Modifier.padding(14.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("$n · $t",fontWeight=FontWeight.Bold);c()}}}
@Composable private fun Revision(cur:String,branches:List<String>,fallback:String,onSelect:(String)->Unit,onAdvanced:()->Unit){var open by remember{mutableStateOf(false)};Column{Box{OutlinedButton(onClick={open=true},modifier=Modifier.fillMaxWidth()){Text(cur.ifBlank{fallback},Modifier.weight(1f));Icon(Icons.Default.ArrowDropDown,null)};DropdownMenu(open,{open=false}){(if(branches.isEmpty())listOf(fallback)else branches).forEach{b->DropdownMenuItem(text={Text(b)},onClick={onSelect(b);open=false})}}};TextButton(onClick=onAdvanced){Text("Advanced revision")}}}
@Composable private fun KeyCard(vm:RepoAuditViewModel,key:String,onKey:(String)->Unit,onSaved:()->Unit){ElevatedCard{Column(Modifier.padding(14.dp)){OutlinedTextField(key,onKey,Modifier.fillMaxWidth(),label={Text("GitHub token")},visualTransformation=PasswordVisualTransformation());Button(onClick={vm.saveGitHubToken(key);onSaved()},enabled=key.isNotBlank()){Text("Connect / replace")};if(vm.githubConfigured())TextButton(onClick=vm::disconnectGitHub){Text("Disconnect")}}}}
@Composable private fun OutputCard(vm:RepoAuditViewModel,onFolder:()->Unit){ElevatedCard{Row(Modifier.padding(14.dp)){OutlinedButton(onClick=onFolder){Text("Choose folder")};Spacer(Modifier.width(8.dp));Button(onClick=vm::exportCurrent){Text("Export")}}}}
@Composable private fun Notice(t:String,d:()->Unit){ElevatedCard{Row(Modifier.padding(12.dp),verticalAlignment=Alignment.CenterVertically){Text(t,Modifier.weight(1f));IconButton(onClick=d){Icon(Icons.Default.Close,"Dismiss")}}}}
@Composable private fun ScopeSummary(p:AuditScopePreview,advanced:()->Unit){ElevatedCard{Column(Modifier.padding(14.dp)){Text("Scope result",fontWeight=FontWeight.Bold);Text("${p.requiredFiles} included · ${p.excludedFiles} excluded · ${p.unresolvedFiles} unresolved");Text("${p.commitSha.take(12)} · ${p.manifestHash.take(12)}",style=MaterialTheme.typography.labelSmall);TextButton(onClick=advanced){Text("Advanced inspection")}}}}
@Composable private fun Preflight(p:AuditPreflight,ok:Boolean,onOk:(Boolean)->Unit,onNotify:()->Unit){ElevatedCard(colors=CardDefaults.elevatedCardColors(containerColor=MaterialTheme.colorScheme.secondaryContainer)){Column(Modifier.padding(14.dp)){Text("4 · Preflight · Audit Standard v${p.methodologyVersion}",fontWeight=FontWeight.Bold);Text("${p.requiredFiles} files · ${p.reviewers} models · ~${p.estimatedRequests} requests");Text("Live team readiness",fontWeight=FontWeight.SemiBold);p.teamReadiness.forEach{Text("• $it",style=MaterialTheme.typography.labelSmall)};Row(verticalAlignment=Alignment.Top){Checkbox(ok,onOk);Text("I understand the validated material is sanitized and sent to the selected providers.",Modifier.padding(top=10.dp))};TextButton(onClick=onNotify){Text("Enable progress notifications")}}}}
@Composable private fun Progress(run:RepoAuditRun,vm:RepoAuditViewModel){val rs=vm.auditReviewerModels();val f=vm.auditChairman();ElevatedCard{Column(Modifier.padding(14.dp)){Text(run.repoFullName,fontWeight=FontWeight.Bold);Text("Stage ${run.stage} · Standard v${run.auditStandardVersion}");run.modelAudits.forEach{a->val i=rs.indexOf(a.model);val role=when{i>=0&&a.model==f->"Reviewer ${i+1} + Final Reviewer";i>=0->"Reviewer ${i+1}";a.model==f->"Final Reviewer";else->"Reviewer"};val pct=if(a.requiredCount==0)0 else a.coveredCount*100/a.requiredCount;Text("$role — ${vm.modelLabel(a.model)}",fontWeight=FontWeight.SemiBold);Text("${a.coveredCount}/${a.requiredCount} evidence-validated ($pct%)${if(a.complete)" ✓" else ""}",style=MaterialTheme.typography.labelSmall);a.error?.let{Text(it,color=MaterialTheme.colorScheme.error)}};run.errors.forEach{(k,v)->Text("$k: $v",color=MaterialTheme.colorScheme.error)};if(run.stage in listOf(RepoAuditStage.SNAPSHOT,RepoAuditStage.INDEPENDENT,RepoAuditStage.PEER_REVIEW,RepoAuditStage.VERIFY,RepoAuditStage.CHAIRMAN))OutlinedButton(onClick=vm::cancel){Text("Cancel")}}}}
@Composable private fun Evidence(run:RepoAuditRun,vm:RepoAuditViewModel){ElevatedCard{Column(Modifier.padding(14.dp)){Text("Independent evidence passes",fontWeight=FontWeight.Bold);run.modelAudits.forEachIndexed{i,a->HorizontalDivider();Text("Reviewer ${i+1} — ${vm.modelLabel(a.model)}",fontWeight=FontWeight.SemiBold);Text("${a.coveredCount}/${a.requiredCount} validated · ${if(a.complete)"complete" else "incomplete"}");a.error?.let{Text(it,color=MaterialTheme.colorScheme.error)};if(a.report.isNotBlank())SelectionContainer{Text(a.report,maxLines=10,overflow=TextOverflow.Ellipsis)}}}}}
@Composable private fun Peer(run:RepoAuditRun,vm:RepoAuditViewModel){ElevatedCard{Column(Modifier.padding(14.dp)){Text("Anonymous peer review",fontWeight=FontWeight.Bold);run.peerReviews.forEachIndexed{i,r->Text("Peer ${i+1} — ${vm.modelLabel(r.model)}");Text(r.error?:r.text,maxLines=6,overflow=TextOverflow.Ellipsis)}}}}
@Composable private fun LongCard(title:String,text:String){var full by remember{mutableStateOf(false)};ElevatedCard{Column(Modifier.padding(14.dp)){Text(title,fontWeight=FontWeight.Bold);SelectionContainer{Text(text,maxLines=if(full)Int.MAX_VALUE else 16,overflow=if(full)TextOverflow.Clip else TextOverflow.Ellipsis)};TextButton(onClick={full=!full}){Text(if(full)"Collapse" else "Show full")}}}}
